// This script is generated by Gemini
using UnityEngine;
using UnityEngine.SceneManagement;

public class RainManager : MonoBehaviour
{
    [Header("Phase Timers")]
    public float prepTime = 60f; 
    private float currentTimer = 0f;
    public bool isRaining = false;

    [Header("Water Objects & Limits")]
    public Transform waterCube;
    public float minWaterY = -0.5f;   
    public float maxWaterY = 2.0f;    
    public float baseWaterSpeed = 0.1f; 

    [Header("Drainages")]
    public DrainageNode[] drainages;

    [Header("Rain Visuals (3D Particles)")]
    [Tooltip("Drag the RainParticleSystem object here")]
    public ParticleSystem rainParticles;

    void Start()
    {
        Vector3 startPos = waterCube.position;
        startPos.y = minWaterY;
        waterCube.position = startPos;

        // Ensure rain is fully stopped at the start
        if (rainParticles != null)
        {
            rainParticles.Stop();
        }
    }

    void Update()
    {
        // 1. Handle Prep Phase
        if (!isRaining)
        {
            currentTimer += Time.deltaTime;
            if (currentTimer >= prepTime)
            {
                isRaining = true;
                Debug.Log("Prep time over! 3D Rain has started.");
                
                // Trigger the Particle System
                if (rainParticles != null)
                {
                    rainParticles.Play();
                }
            }
            return; 
        }

        // 2. Calculate Total Debris
        int totalDebris = 0;
        foreach (DrainageNode node in drainages)
        {
            if (node != null) totalDebris += node.obstacleLevel;
        }

        // 3. Move the Water
        float flowRate = (totalDebris - 10f) * baseWaterSpeed;
        Vector3 newPos = waterCube.position;
        newPos.y += flowRate * Time.deltaTime;
        newPos.y = Mathf.Max(newPos.y, minWaterY);
        waterCube.position = newPos;

        // 4. Check for Game Over
        if (waterCube.position.y >= maxWaterY)
        {
            GameOver();
        }
    }

    void GameOver()
    {
        Debug.Log("Game Over! Restarting Scene...");
        SceneManager.LoadScene(SceneManager.GetActiveScene().name);
    }
}